INSERT INTO `email_template` (`name`, `name_key`, `subject`, `design`, `html`, `id_lang`, `is_active`, `can_delete`) SELECT 'Password changed', 'password_changed_5', 'Your password has been changed', '{"editor":"grapes","mjml":"<mjml>\\n  <mj-head>\\n    <mj-font name=\\"Poppins\\" href=\\"https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700\\"></mj-font>\\n    <mj-attributes>\\n      <mj-all font-family=\\"Poppins, Arial, Helvetica, sans-serif\\"></mj-all>\\n      <mj-text font-size=\\"15px\\" color=\\"#333333\\" line-height=\\"1.6\\"></mj-text>\\n    </mj-attributes>\\n  </mj-head>\\n  <mj-body background-color=\\"#F4F5F7\\" width=\\"600px\\">\\n    <mj-section background-color=\\"#163986\\" padding=\\"20px 24px\\"><mj-column><mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"20px\\" font-weight=\\"700\\" color=\\"#ffffff\\" padding=\\"0\\">Bial Regional Academy</mj-text></mj-column></mj-section>\\n    <mj-section background-color=\\"#ffffff\\" padding=\\"28px 24px 8px\\"><mj-column>\\n        <mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"22px\\" font-weight=\\"700\\" color=\\"#163986\\">Hello {{name}},</mj-text>\\n        <mj-text>The password of your Bial Regional Academy account has been changed.</mj-text>\\n        <mj-text>If it was you, there is nothing else to do. If you do not recognise this change, recover access to your account immediately and contact us.</mj-text>\\n    </mj-column></mj-section>\\n    \\n    <mj-section background-color=\\"#ffffff\\" padding=\\"0 24px 28px\\"><mj-column><mj-button background-color=\\"#163986\\" color=\\"#ffffff\\" border-radius=\\"6px\\" font-weight=\\"600\\" href=\\"{{url}}\\">Recover my account</mj-button></mj-column></mj-section>\\n    <mj-section background-color=\\"#F4F5F7\\" padding=\\"20px 24px\\"><mj-column><mj-text align=\\"center\\" font-size=\\"12px\\" color=\\"#8A8D98\\" line-height=\\"1.6\\">Bial Regional Academy<br/>Thi