=\\"0\\" cellspacing=\\"0\\" role=\\"presentation\\" style=\\"vertical-align:top;\\" width=\\"100%\\"\\n      >\\n        <tbody>\\n          \\n              <tr>\\n                <td\\n                   align=\\"center\\" style=\\"font-size:0px;padding:10px 25px;word-break:break-word;\\"\\n                >\\n                  \\n      <div\\n         style=\\"font-family:Poppins, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.6;text-align:center;color:#8A8D98;\\"\\n      >Bial Regional Academy<br/>This e-mail was sent automatically, please do not reply.</div>\\n    \\n                </td>\\n              </tr>\\n            \\n        </tbody>\\n      </table>\\n    \\n      </div>\\n    \\n          <!--[if mso | IE]></td></tr></table><![endif]-->\\n              </td>\\n            </tr>\\n          </tbody>\\n        </table>\\n        \\n      </div>\\n    \\n      \\n      <!--[if mso | IE]></td></tr></table><![endif]-->\\n    \\n    \\n      </div>\\n    \\n  </body>\\n</html>\\n  "', 5, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `email_template` WHERE `name_key` = 'password_changed_5');
INSERT INTO `email_template` (`name`, `name_key`, `subject`, `design`, `html`, `id_lang`, `is_active`, `can_delete`) SELECT 'Mot de passe modifié', 'password_changed_6', 'Votre mot de passe a été modifié', '{"editor":"grapes","mjml":"<mjml>\\n  <mj-head>\\n    <mj-font name=\\"Poppins\\" href=\\"https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700\\"></mj-font>\\n    <mj-attributes>\\n      <mj-all font-family=\\"Poppins, Arial, Helvetica, sans-serif\\"></mj-all>\\n      <mj-text font-size=\\"15px\\" color=\\"#333333\\" line-height=\\"1.6\\"></mj-text>\\n    </mj-attributes>\\n  </mj-head>\\n  <mj-body background-color=\\"#F4F5F7\\" width=\\"600px\\">\\n    <mj-section background-color=\\"#163986\\" padding=\\"20px 24px\\"><mj-column><mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"20px\\" font-weight=\\"700\\" color=\\"#ffffff\\" padding=\\"0\\">Bial Regional Academy</mj-text></mj-column></mj-section>\\n    <mj-section background-color=\\"#ffffff\\" padding=\\"28px 24px 8px\\"><mj-column>\\n        <mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"22px\\" font-weight=\\"700\\" color=\\"#163986\\">Bonjour {{name}},</mj-text>\\n        <mj-text>Le mot de passe de votre compte Bial Regional Academy a été modifié.</mj-text>\\n        <mj-text>Si c’était vous, vous n’avez rien à faire. Si vous ne reconnaissez pas cette modification, récupérez immédiatement l’accès à votre compte et contactez-nous.</mj-text>\\n    </mj-column></mj-section>\\n    \\n    <mj-section background-color=\\"#ffffff\\" padding=\\"0 24px 28px\\"><mj-column><mj-button background-color=\\"#163986\\" color=\\"#ffffff\\" border-radius=\\"6px\\" font-weight=\\"600\\" href=\\"{{url}}\\">Récupérer mon compte</mj-button></mj-column></mj-section>\\n    <mj-section background-color=\\"#F4F5F7\\" padding=\\"20px 24px\\"><mj-column><mj-text align=\\"center\\" font-size=\\"12px\\" color=\\"#8A8D98\\" line-height=\\"1.6\\">Bi