"0\\"><tr><td class=\\"\\" style=\\"vertical-align:top;width:552px;\\" ><![endif]-->\\n            \\n      <div\\n         class=\\"mj-column-per-100 mj-outlook-group-fix\\" style=\\"font-size:0px;text-align:left;direction:ltr;display:inline-block;vertical-align:top;width:100%;\\"\\n      >\\n        \\n      <table\\n         border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" role=\\"presentation\\" style=\\"vertical-align:top;\\" width=\\"100%\\"\\n      >\\n        <tbody>\\n          \\n              <tr>\\n                <td\\n                   align=\\"center\\" style=\\"font-size:0px;padding:10px 25px;word-break:break-word;\\"\\n                >\\n                  \\n      <div\\n         style=\\"font-family:Poppins, Arial, Helvetica, sans-serif;font-size:12px;line-height:1.6;text-align:center;color:#8A8D98;\\"\\n      >Bial Regional Academy<br/>Este e-mail foi enviado automaticamente, por favor não responda.</div>\\n    \\n                </td>\\n              </tr>\\n            \\n        </tbody>\\n      </table>\\n    \\n      </div>\\n    \\n          <!--[if mso | IE]></td></tr></table><![endif]-->\\n              </td>\\n            </tr>\\n          </tbody>\\n        </table>\\n        \\n      </div>\\n    \\n      \\n      <!--[if mso | IE]></td></tr></table><![endif]-->\\n    \\n    \\n      </div>\\n    \\n  </body>\\n</html>\\n  "', 3, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `email_template` WHERE `name_key` = 'contact_received_3');
INSERT INTO `email_template` (`name`, `name_key`, `subject`, `design`, `html`, `id_lang`, `is_active`, `can_delete`) SELECT 'Mensaje de contacto recibido', 'contact_received_4', 'Hemos recibido su mensaje', '{"editor":"grapes","mjml":"<mjml>\\n  <mj-head>\\n    <mj-font name=\\"Poppins\\" href=\\"https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700\\"></mj-font>\\n    <mj-attributes>\\n      <mj-all font-family=\\"Poppins, Arial, Helvetica, sans-serif\\"></mj-all>\\n      <mj-text font-size=\\"15px\\" color=\\"#333333\\" line-height=\\"1.6\\"></mj-text>\\n    </mj-attributes>\\n  </mj-head>\\n  <mj-body background-color=\\"#F4F5F7\\" width=\\"600px\\">\\n    <mj-section background-color=\\"#163986\\" padding=\\"20px 24px\\"><mj-column><mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"20px\\" font-weight=\\"700\\" color=\\"#ffffff\\" padding=\\"0\\">Bial Regional Academy</mj-text></mj-column></mj-section>\\n    <mj-section background-color=\\"#ffffff\\" padding=\\"28px 24px 8px\\"><mj-column>\\n        <mj-text font-family=\\"Ryker, Poppins, Arial, Helvetica, sans-serif\\" font-size=\\"22px\\" font-weight=\\"700\\" color=\\"#163986\\">Hola {{name}},</mj-text>\\n        <mj-text>Gracias por contactarnos. Hemos recibido su mensaje sobre «{{subject}}» y le responderemos lo antes posible.</mj-text>\\n    </mj-column></mj-section>\\n    \\n    <mj-section background-color=\\"#ffffff\\" padding=\\"0 24px 12px\\"><mj-column><mj-spacer height=\\"8px\\"></mj-spacer></mj-column></mj-section>\\n    <mj-section background-color=\\"#F4F5F7\\" padding=\\"20px 24px\\"><mj-column><mj-text align=\\"center\\" font-size=\\"12px\\" color=\\"#8A8D98\\" line-height=\\"1.6\\">Bial Regional Academy<br/>Este correo se envió automáticamente, por favor no responda.</mj-text></mj-column></mj-section>\\n  </mj-body>\\n</mjml>"}', '"<!doctype html>\\n<html lang=\\"und\\" dir=\\"auto\\" xmlns=\\"http://www.w3.org/1999/xhtml\\" xmlns:v=\\"urn:schema